// Generated by local model ornith:9b (2 review rounds), verified by Claude.
import React, { useEffect, useState } from "react";
import { quantsyncApi } from "../api/quantsyncApi";
import { describeDataStatus } from "../lib/dataStatus";

const TONES: Record<string, [string, string]> = {
  ok: ["rgba(22,163,74,.12)", "var(--up, #16a34a)"],
  warn: ["rgba(245,158,11,.14)", "#b45309"],
  bad: ["rgba(220,38,38,.12)", "var(--down, #dc2626)"],
  unknown: ["rgba(148,163,184,.15)", "var(--ink2, #64748b)"],
};

export default function DataStatusBadge({ compact = false }: { compact?: boolean }) {
  const [status, setStatus] = useState<any | null>(null);

  useEffect(() => {
    let alive = true;
    const load = () => {
      quantsyncApi.getDataStatus().then((s) => {
        if (alive) setStatus(s);
      }).catch(() => {});
    };
    load();
    const interval = setInterval(load, 300000);
    return () => {
      alive = false;
      clearInterval(interval);
    };
  }, []);

  if (status === null) return null;
  const d = describeDataStatus(status);
  const [bg, fg] = TONES[d.tone] || TONES.unknown;

  return (
    <div role="status" title={d.detail} style={{
      display: "inline-flex", alignItems: "center", flexWrap: "wrap", gap: 6, padding: compact ? "2px 8px" : "6px 12px",
      borderRadius: compact ? 999 : 12, maxWidth: "100%", lineHeight: 1.35, fontSize: compact ? 11 : 12, fontWeight: 600, background: bg, color: fg,
    }}>
      <span style={{ display: "inline-block", width: 6, height: 6, borderRadius: "50%", background: "currentColor" }} />
      <span style={{ whiteSpace: "nowrap" }}>{d.label}</span>
      {!compact && (d.tone === "warn" || d.tone === "bad") ? (
        <span style={{ opacity: 0.8, fontWeight: 500 }}> · {d.detail}</span>
      ) : null}
    </div>
  );
}
